<?php
class Reporte_abordaje_model extends CI_Model{
 public function usuario_tiene_rol($u,$r){return !empty($this->db->query("SELECT 1 x FROM usuario u INNER JOIN rol_usuario ru ON ru.tipousuario_id=u.tipousuario_id WHERE u.usuario_id=? AND ru.rol_id=? AND ru.rolusuario_asignado=1 LIMIT 1",array((int)$u,(int)$r))->row_array());}
 public function viajes($f){return $this->db->query("SELECT v.viaje_id,v.viaje_fechasalida,v.viaje_horasalida,COALESCE(r.ruta_nombre,CONCAT_WS(' - ',r.inicio_ruta,r.fin_ruta)) ruta FROM viaje v LEFT JOIN ruta r ON r.ruta_id=v.ruta_id WHERE v.viaje_fechasalida BETWEEN ? AND ? ORDER BY v.viaje_fechasalida DESC,v.viaje_horasalida DESC",array($f['desde'],$f['hasta']))->result_array();}
 private function where($f,&$p){$w="p.estado_id=54 AND v.viaje_fechasalida BETWEEN ? AND ?";$p=array($f['desde'],$f['hasta']);if($f['viaje_id']>0){$w.=" AND p.viaje_id=?";$p[]=$f['viaje_id'];}return $w;}
 public function resumen($f){$p=array();$w=$this->where($f,$p);return $this->db->query("SELECT COUNT(*) vendidos,SUM(CASE WHEN a.abordaje_id IS NOT NULL THEN 1 ELSE 0 END) abordados,SUM(CASE WHEN a.abordaje_id IS NULL THEN 1 ELSE 0 END) no_show,CASE WHEN COUNT(*)>0 THEN SUM(CASE WHEN a.abordaje_id IS NULL THEN 1 ELSE 0 END)*100/COUNT(*) ELSE 0 END tasa_no_show FROM pasaje p INNER JOIN viaje v ON v.viaje_id=p.viaje_id LEFT JOIN pasaje_abordaje a ON a.pasaje_id=p.pasaje_id WHERE $w",$p)->row_array();}
 public function detalle($f){$p=array();$w=$this->where($f,$p);if($f['solo_no_show']==1)$w.=" AND a.abordaje_id IS NULL";$sql="SELECT p.pasaje_id,p.pasaje_numero,p.pasaje_nombre pasajero,p.pasaje_documento documento,COALESCE(va.asiento_numero,p.asiento_id) asiento,CONCAT('#',v.viaje_id,' - ',v.viaje_fechasalida,' ',TIME_FORMAT(v.viaje_horasalida,'%H:%i'),' - ',COALESCE(r.ruta_nombre,CONCAT_WS(' - ',r.inicio_ruta,r.fin_ruta))) viaje,CASE WHEN a.abordaje_id IS NOT NULL THEN 'ABORDADO' ELSE 'NO SHOW' END estado_abordaje,a.abordaje_fecha,a.abordaje_hora,a.abordaje_terminal terminal FROM pasaje p INNER JOIN viaje v ON v.viaje_id=p.viaje_id LEFT JOIN ruta r ON r.ruta_id=v.ruta_id LEFT JOIN asientos va ON va.asiento_id=p.asiento_id LEFT JOIN pasaje_abordaje a ON a.pasaje_id=p.pasaje_id WHERE $w ORDER BY v.viaje_fechasalida DESC,v.viaje_horasalida DESC,p.pasaje_numero";return $this->db->query($sql,$p)->result_array();}
}
